{
  "name": "openartifact",
  "version": "0.1.0",
  "private": true,
  "description": "Markdown slide decks rendered in the browser, with a print stylesheet that makes PDF export work.",
  "type": "module",
  "license": "MIT",
  "author": "Samuel Colvin <s@muelcolvin.com>",
  "homepage": "https://github.com/samuelcolvin/openartifact#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/samuelcolvin/openartifact.git"
  },
  "packageManager": "pnpm@10.22.0",
  "scripts": {
    "build": "esbuild src/main.ts --bundle --format=iife --target=es2022 --loader:.css=text --minify --outfile=dist/openartifact.js",
    "dev": "esbuild src/main.ts --bundle --format=iife --target=es2022 --loader:.css=text --outfile=dist/openartifact.js --watch",
    "typecheck": "tsc --noEmit",
    "lint": "biome check .",
    "format": "biome check --fix ."
  },
  "dependencies": {
    "highlight.js": "^11.12.0",
    "markdown-it": "^15.0.2"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.5.14",
    "@types/markdown-it": "^14.2.0",
    "esbuild": "^0.28.2",
    "typescript": "^7.0.2"
  }
}

const path = require('path')

module.exports = {
  entry: './src/index.ts',
  output: {
    filename: 'worker.js',
    path: path.join(__dirname, 'dist'),
  },
  devtool: 'cheap-module-source-map',
  mode: 'development',
  resolve: {
    extensions: ['.ts', '.js'],
  },
  module: {
    rules: [
      {
        test: /\.tsx?$/,
        loader: 'ts-loader',
        options: {
          // transpileOnly is useful to skip typescript checks occasionally:
          // transpileOnly: true,
        },
      },
    ],
  },
}

{
	"name": "cf-request-error",
	"version": "0.0.0",
	"private": true,
	"scripts": {
		"deploy": "wrangler deploy",
		"dev": "wrangler dev",
		"start": "wrangler dev",
		"test": "vitest",
		"cf-typegen": "wrangler types"
	},
	"devDependencies": {
		"@cloudflare/vitest-pool-workers": "^0.8.19",
		"typescript": "^5.5.2",
		"vitest": "~3.2.0",
		"wrangler": "^4.42.2"
	}
}

{
	"printWidth": 140,
	"singleQuote": true,
	"semi": true,
	"useTabs": true
}

